import React, { useState, useEffect } from "react";
import { storiesAPI, postsAPI, reelsAPI } from "../services/api";
import StoryForm from "../components/StoryForm";
import PostForm from "../components/PostForm";
import ReelForm from "../components/ReelForm";
import "./Dashboard.css";

const Dashboard = ({ user }) => {
  const [activeTab, setActiveTab] = useState("stories");
  const [stories, setStories] = useState([]);
  const [posts, setPosts] = useState([]);
  const [reels, setReels] = useState([]);
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    loadData();
  }, [activeTab]);

  const loadData = async () => {
    setLoading(true);
    try {
      if (activeTab === "stories") {
        const { data } = await storiesAPI.getAll();
        setStories(data);
      } else if (activeTab === "posts") {
        const { data } = await postsAPI.getAll();
        setPosts(data);
      } else if (activeTab === "reels") {
        const { data } = await reelsAPI.getAll();
        setReels(data);
      }
    } catch (error) {
      console.error("Error loading data:", error);
    } finally {
      setLoading(false);
    }
  };

  const handleDelete = async (id, type) => {
    if (window.confirm("Are you sure you want to delete this?")) {
      try {
        if (type === "story") {
          await storiesAPI.delete(id);
          setStories(stories.filter((s) => s._id !== id));
        } else if (type === "post") {
          await postsAPI.delete(id);
          setPosts(posts.filter((p) => p._id !== id));
        } else if (type === "reel") {
          await reelsAPI.delete(id);
          setReels(reels.filter((r) => r._id !== id));
        }
      } catch (error) {
        alert("Error deleting item");
      }
    }
  };

  return (
    <div className="dashboard">
      <header className="dashboard-header">
        <h1>KiwiGram Admin Dashboard</h1>
        <p>Welcome, {user?.name}</p>
      </header>

      <div className="tabs">
        <button
          className={activeTab === "stories" ? "active" : ""}
          onClick={() => setActiveTab("stories")}
        >
          Stories
        </button>
        <button
          className={activeTab === "posts" ? "active" : ""}
          onClick={() => setActiveTab("posts")}
        >
          Posts
        </button>
        <button
          className={activeTab === "reels" ? "active" : ""}
          onClick={() => setActiveTab("reels")}
        >
          Reels
        </button>
      </div>

      <div className="content">
        {activeTab === "stories" && (
          <>
            <StoryForm onSuccess={loadData} />
            <div className="items-list">
              {stories.map((story) => (
                <div key={story._id} className="item-card">
                  <img src={story.image} alt="Story" />
                  <p>{story.caption}</p>
                  <button
                    onClick={() => handleDelete(story._id, "story")}
                    className="delete-btn"
                  >
                    Delete
                  </button>
                </div>
              ))}
            </div>
          </>
        )}

        {activeTab === "posts" && (
          <>
            <PostForm onSuccess={loadData} />
            <div className="items-list">
              {posts.map((post) => (
                <div key={post._id} className="item-card">
                  <img src={post.image} alt="Post" />
                  <h4>{post.caption}</h4>
                  <p>Likes: {post.likes}</p>
                  <button
                    onClick={() => handleDelete(post._id, "post")}
                    className="delete-btn"
                  >
                    Delete
                  </button>
                </div>
              ))}
            </div>
          </>
        )}

        {activeTab === "reels" && (
          <>
            <ReelForm onSuccess={loadData} />
            <div className="items-list">
              {reels.map((reel) => (
                <div key={reel._id} className="item-card">
                  <img src={reel.image} alt="Reel" />
                  <h4>{reel.caption}</h4>
                  <p>
                    Views: {reel.views} | Likes: {reel.likes}
                  </p>
                  <button
                    onClick={() => handleDelete(reel._id, "reel")}
                    className="delete-btn"
                  >
                    Delete
                  </button>
                </div>
              ))}
            </div>
          </>
        )}
      </div>
    </div>
  );
};

export default Dashboard;
